using System;using System.Collections.Generic;using System.IO;using UnityEngine;
namespace RebirthEntityStudio {
 internal struct BodyWoundHit {public Vector3 point,normal;public Vector2 uv;}
 internal sealed class BodyWoundSurface {
  readonly Vector3[] p,n;readonly Vector2[] uv;readonly int[] triangles;
  public BodyWoundSurface(Mesh mesh){p=mesh.vertices;n=mesh.normals;uv=mesh.uv;triangles=mesh.triangles;if(p.Length!=n.Length||p.Length!=uv.Length)throw new InvalidDataException("Wound placement needs body normals and UVs");}
  BodyWoundSurface(Vector3[] p,Vector3[] n,Vector2[] uv,int[] triangles){this.p=p;this.n=n;this.uv=uv;this.triangles=triangles;}
  public BodyWoundSurface Local(Vector3 center,float radius){var selection=new List<int>();var bounds=new Bounds(center,Vector3.one*radius*2);for(int i=0;i<triangles.Length;i+=3){var b=new Bounds(p[triangles[i]],Vector3.zero);b.Encapsulate(p[triangles[i+1]]);b.Encapsulate(p[triangles[i+2]]);if(b.Intersects(bounds)){selection.Add(triangles[i]);selection.Add(triangles[i+1]);selection.Add(triangles[i+2]);}}return new BodyWoundSurface(p,n,uv,selection.ToArray());}
  public bool Pick(Ray ray,out BodyWoundHit hit){hit=new BodyWoundHit();float nearest=float.PositiveInfinity;for(int k=0;k<triangles.Length;k+=3){int a=triangles[k],b=triangles[k+1],c=triangles[k+2];Vector3 e1=p[b]-p[a],e2=p[c]-p[a],h=Vector3.Cross(ray.direction,e2);float determinant=Vector3.Dot(e1,h);if(Mathf.Abs(determinant)<1e-9f)continue;float inverse=1/determinant;Vector3 s=ray.origin-p[a];float u=inverse*Vector3.Dot(s,h);if(u<0||u>1)continue;Vector3 q=Vector3.Cross(s,e1);float v=inverse*Vector3.Dot(ray.direction,q);if(v<0||u+v>1)continue;float distance=inverse*Vector3.Dot(e2,q);if(distance<0||distance>=nearest)continue;nearest=distance;hit.point=ray.GetPoint(distance);hit.normal=(n[a]*(1-u-v)+n[b]*u+n[c]*v).normalized;hit.uv=uv[a]*(1-u-v)+uv[b]*u+uv[c]*v;}return !float.IsPositiveInfinity(nearest);}
  public BodyWoundHit Locate(BodyDeepWound anchor,float height){bool found=false;float best=float.PositiveInfinity;var hit=new BodyWoundHit();for(int k=0;k<triangles.Length;k+=3){int a=triangles[k],b=triangles[k+1],c=triangles[k+2];Vector2 e1=uv[b]-uv[a],e2=uv[c]-uv[a],d=anchor.uv-uv[a];float det=e1.x*e2.y-e1.y*e2.x;if(Mathf.Abs(det)<1e-12f)continue;float u=(d.x*e2.y-d.y*e2.x)/det,v=(e1.x*d.y-e1.y*d.x)/det;if(u<-.00001f||v<-.00001f||u+v>1.00001f)continue;Vector3 point=p[a]*(1-u-v)+p[b]*u+p[c]*v;float score=(point/height-anchor.referencePoint).sqrMagnitude;if(score>=best)continue;best=score;found=true;hit=new BodyWoundHit{point=point,normal=(n[a]*(1-u-v)+n[b]*u+n[c]*v).normalized,uv=anchor.uv};}if(!found)throw new InvalidDataException("Deep wound anchor is outside this body's UV layout");return hit;}
  static Vector3 BarycentricClosest(Vector3 point,Vector3 a,Vector3 b,Vector3 c){Vector3 ab=b-a,ac=c-a,ap=point-a;float d1=Vector3.Dot(ab,ap),d2=Vector3.Dot(ac,ap);if(d1<=0&&d2<=0)return new Vector3(1,0,0);Vector3 bp=point-b;float d3=Vector3.Dot(ab,bp),d4=Vector3.Dot(ac,bp);if(d3>=0&&d4<=d3)return new Vector3(0,1,0);float vc=d1*d4-d3*d2;if(vc<=0&&d1>=0&&d3<=0){float v=d1/(d1-d3);return new Vector3(1-v,v,0);}Vector3 cp=point-c;float d5=Vector3.Dot(ab,cp),d6=Vector3.Dot(ac,cp);if(d6>=0&&d5<=d6)return new Vector3(0,0,1);float vb=d5*d2-d1*d6;if(vb<=0&&d2>=0&&d6<=0){float w=d2/(d2-d6);return new Vector3(1-w,0,w);}float va=d3*d6-d5*d4;if(va<=0&&d4-d3>=0&&d5-d6>=0){float w=(d4-d3)/((d4-d3)+(d5-d6));return new Vector3(0,1-w,w);}float denominator=va+vb+vc;if(Mathf.Abs(denominator)<1e-20f)return new Vector3(1,0,0);float y=vb/denominator,z=vc/denominator;return new Vector3(1-y-z,y,z);}
  public float SignedDistance(Vector3 point){float best=float.PositiveInfinity,signed=0;for(int k=0;k<triangles.Length;k+=3){int a=triangles[k],b=triangles[k+1],c=triangles[k+2];Vector3 w=BarycentricClosest(point,p[a],p[b],p[c]),q=p[a]*w.x+p[b]*w.y+p[c]*w.z;float distance=(point-q).sqrMagnitude;if(distance>=best)continue;best=distance;Vector3 normal=(n[a]*w.x+n[b]*w.y+n[c]*w.z).normalized;signed=Vector3.Dot(point-q,normal);}if(float.IsPositiveInfinity(best))throw new InvalidOperationException("No skin surface near deep wound");return signed;}
 }
}
